import React, { useState } from 'react';
import SlideCard from './components/SlideCard';
import VerticalNav from './components/VerticalNav';
import ParallaxBg from './components/ParallaxBg';
import TypewriterText from './components/TypewriterText';
import FlipCard from './components/FlipCard';
import AnimatedEmail from './components/AnimatedEmail';
import { Shield, User, AlertTriangle, Mail, Eye, Search, Zap, CheckCircle, Settings, CaseSensitive, Wrench, MessageCircle, Heart } from 'lucide-react';

const phishingTypes = [
  {
    title: 'Spear Phishing',
    desc: 'Serangan tertarget ke individu tertentu dengan data personal.'
  },
  {
    title: 'Whaling',
    desc: 'Menargetkan eksekutif perusahaan atau VIP.'
  },
  {
    title: 'Clone Phishing',
    desc: 'Email asli diduplikasi lalu diubah link/lampirannya.'
  },
  {
    title: 'BEC',
    desc: 'Business Email Compromise, penipuan transfer dana.'
  },
  {
    title: 'Vishing',
    desc: 'Phishing via telepon.'
  },
  {
    title: 'Smishing',
    desc: 'Phishing via SMS.'
  },
];

const slides = [
  {
    id: 'slide1',
    type: 'title',
    title: 'Phishing 101 - Jangan Jadi Korban!',
    subtitle: 'Belajar Mengenali dan Menghindari Serangan Phishing',
    icon: Shield,
    logo: '/logo-hacktiv8.png',
  },
  {
    id: 'slide2',
    type: 'speaker',
    name: 'Kiell Tampubolon',
    role: 'Cybersecurity Engineer, Singapore',
    photo: '/IMG_8642.jpg',
  },
  {
    id: 'slide3',
    type: 'definition',
    title: 'Apa itu Phishing?',
    analogy: 'Penipu berdasi',
    desc: 'Teknik manipulasi sosial untuk mencuri data sensitif melalui email/pesan palsu. 90% serangan cyber dimulai dari phishing (Verizon DBIR).',
  },
  {
    id: 'slide4',
    type: 'types',
    title: 'Jenis-jenis Phishing',
    types: phishingTypes,
  },
  {
    id: 'slide5',
    type: 'signs',
    title: 'Ciri-ciri Email Phishing',
  },
  {
    id: 'slide6',
    type: 'demo',
    title: 'Demo Analisis Email',
    video: 'https://www.youtube.com/embed/1c1w0pQOa2Q', // Placeholder
  },
  {
    id: 'slide7',
    type: 'simulation',
    title: 'Simulasi Kirim Phishing Email',
    desc: 'Gunakan GoPhish / Template Demo. Disclaimer: Edukasi saja, tidak dikirim ke peserta.',
  },
  {
    id: 'slide8',
    type: 'tips',
    title: 'Tips Mendeteksi Phishing',
    tips: [
      'Hover sebelum klik',
      'Jangan tergesa-gesa',
      'Periksa domain/email',
      'Verifikasi ke sumber resmi',
    ],
  },
  {
    id: 'slide9',
    type: 'protection',
    title: 'Strategi Perlindungan',
    points: [
      'Untuk Individu: MFA, password manager, awareness',
      'Untuk Perusahaan: Filter email, DMARC/SPF, simulasi phishing berkala',
    ],
  },
  {
    id: 'slide10',
    type: 'case',
    title: 'Studi Kasus Nyata',
    cases: [
      'BEC rugi $10 juta',
      'Phishing LinkedIn rekrutmen palsu',
    ],
  },
  {
    id: 'slide11',
    type: 'tools',
    title: 'Tools Gratis untuk Melindungi Diri',
    tools: [
      'VirusTotal',
      'HaveIBeenPwned',
      'Password manager (Bitwarden)',
      'Email header analyzer',
    ],
  },
  {
    id: 'slide12',
    type: 'qna',
    title: 'Tanya Jawab',
    desc: 'Silakan ajukan pertanyaan, bahkan yang paling sederhana. Karena hacker tidak butuh celah besar, cukup satu klik dari Anda.',
  },
  {
    id: 'slide13',
    type: 'closing',
    title: 'Penutup & CTA',
    points: [
      'Phishing bisa dicegah',
      'Edukasi & kesadaran adalah kunci',
      'Jangan klik sebelum yakin!',
    ],
    desc: 'Hari ini, mulai cek ulang email yang Anda terima. Jangan mudah percaya, jangan panik, selalu verifikasi.',
  },
];

function App() {
  const [current, setCurrent] = useState(0);
  const slide = slides[current];

  // Fullscreen handler
  const handleFullscreen = () => {
    const elem = document.documentElement;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      elem.requestFullscreen();
    }
  };

  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-orange-500 via-orange-600 to-red-700 flex items-center justify-center relative overflow-x-hidden">
      {/* Logo Hacktiv8 kanan atas */}
      {slide.logo && (
        <img src={slide.logo} alt="Hacktiv8 Logo" className="fixed top-6 right-8 w-24 h-auto z-40 drop-shadow-lg" />
      )}
      {/* Slide Content */}
      <div className="w-full flex items-center justify-center min-h-screen">
        <SlideCard>
          {/* Slide 1: Judul */}
          {slide.type === 'title' && (
            <div className="flex flex-col items-center">
              <Shield size={64} className="text-orange-600 drop-shadow-lg animate-bounce mb-6" />
              <h1 className="slide-title text-4xl md:text-5xl font-extrabold mb-4 text-white">
                <TypewriterText text={slide.title} speed={40} />
              </h1>
              <h2 className="slide-subtitle text-xl md:text-2xl text-orange-100 font-medium">
                <TypewriterText text={slide.subtitle} speed={20} />
              </h2>
            </div>
          )}
          {/* Slide 2: Tentang Pembicara */}
          {slide.type === 'speaker' && (
            <ParallaxBg bgImage="/IMG_8642.jpg" className="rounded-2xl overflow-hidden">
              <div className="flex flex-col items-center bg-black/40 p-8 rounded-2xl">
                <div className="w-32 h-32 rounded-full overflow-hidden shadow-lg mb-4 border-4 border-orange-200">
                  <img src={slide.photo} alt="Foto Pembicara" className="object-cover w-full h-full" />
                </div>
                <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.name}</h2>
                <div className="slide-subtitle text-orange-100 mb-2">{slide.role}</div>
                <div className="slide-text text-white/90 text-center">Cybersecurity enthusiast, passionate about phishing awareness and digital safety.</div>
              </div>
            </ParallaxBg>
          )}
          {/* Slide 3: Apa itu Phishing */}
          {slide.type === 'definition' && (
            <div className="flex flex-col items-center">
              <div className="mb-4">
                <img src="https://cdn.pixabay.com/photo/2017/01/31/13/14/phishing-2022273_1280.png" alt="Ilustrasi Phishing" className="w-32 h-32 object-contain mx-auto" />
              </div>
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <div className="slide-text text-white/90 text-center mb-2">
                <TypewriterText text={slide.desc} speed={20} />
              </div>
              <div className="text-orange-200 italic text-lg">Analog: <span className="font-bold">{slide.analogy}</span> <span role="img" aria-label="tie">👔</span></div>
            </div>
          )}
          {/* Slide 4: Jenis-jenis Phishing */}
          {slide.type === 'types' && (
            <div className="flex flex-wrap gap-4 justify-center">
              {slide.types.map((t, idx) => (
                <FlipCard
                  key={t.title}
                  front={<div className="font-bold text-orange-700 text-lg">{t.title}</div>}
                  back={<div className="text-white text-center text-sm p-2">{t.desc}</div>}
                />
              ))}
            </div>
          )}
          {/* Slide 5: Ciri-ciri Email Phishing */}
          {slide.type === 'signs' && (
            <AnimatedEmail />
          )}
          {/* Slide 6: Demo Analisis Email */}
          {slide.type === 'demo' && (
            <div className="flex flex-col items-center">
              <div className="w-full aspect-video rounded-xl overflow-hidden shadow-lg mb-4">
                <iframe
                  src={slide.video}
                  title="Demo Analisis Email"
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                  className="w-full h-full"
                ></iframe>
              </div>
              <div className="text-white/90 text-center">Contoh analisis email phishing menggunakan tools online.</div>
            </div>
          )}
          {/* Slide 7: Simulasi Kirim Phishing Email */}
          {slide.type === 'simulation' && (
            <div className="flex flex-col items-center">
              <Zap size={48} className="text-orange-500 mb-4 animate-pulse" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <div className="slide-text text-white/90 text-center">{slide.desc}</div>
            </div>
          )}
          {/* Slide 8: Tips Mendeteksi Phishing */}
          {slide.type === 'tips' && (
            <div className="flex flex-col items-center">
              <CheckCircle size={48} className="text-orange-400 mb-4 animate-bounce" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.tips.map((tip, idx) => (
                  <li key={tip} className="hover:text-orange-300 transition-colors">{tip}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 9: Strategi Perlindungan */}
          {slide.type === 'protection' && (
            <div className="flex flex-col items-center">
              <Settings size={48} className="text-orange-400 mb-4 animate-spin-slow" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.points.map((pt, idx) => (
                  <li key={pt} className="hover:text-orange-300 transition-colors">{pt}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 10: Studi Kasus Nyata */}
          {slide.type === 'case' && (
            <div className="flex flex-col items-center">
              <CaseSensitive size={48} className="text-orange-400 mb-4 animate-pulse" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.cases.map((c, idx) => (
                  <li key={c} className="hover:text-orange-300 transition-colors">{c}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 11: Tools Gratis untuk Melindungi Diri */}
          {slide.type === 'tools' && (
            <div className="flex flex-col items-center">
              <Wrench size={48} className="text-orange-400 mb-4 animate-spin" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.tools.map((tool, idx) => (
                  <li key={tool} className="hover:text-orange-300 transition-colors">{tool}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 12: Tanya Jawab */}
          {slide.type === 'qna' && (
            <div className="flex flex-col items-center">
              <MessageCircle size={48} className="text-orange-400 mb-4 animate-bounce" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <div className="slide-text text-white/90 text-center">{slide.desc}</div>
            </div>
          )}
          {/* Slide 13: Penutup & CTA */}
          {slide.type === 'closing' && (
            <div className="flex flex-col items-center">
              <Heart size={48} className="text-orange-400 mb-4 animate-bounce" />
              <h2 className="slide-title text-2xl md:text-3xl font-bold text-white mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2 mb-2">
                {slide.points.map((pt, idx) => (
                  <li key={pt} className="hover:text-orange-300 transition-colors">{pt}</li>
                ))}
              </ul>
              <div className="slide-text text-white/90 text-center">{slide.desc}</div>
            </div>
          )}
        </SlideCard>
      </div>
      {/* Vertical Navigation */}
      <VerticalNav
        current={current}
        total={slides.length}
        onPrev={() => setCurrent((c) => Math.max(0, c - 1))}
        onNext={() => setCurrent((c) => Math.min(slides.length - 1, c + 1))}
        onFullscreen={handleFullscreen}
      />
    </div>
  );
}

export default App;
